"""Existing passive resource telemetry program, shared by all mission campaigns."""
TELEMETRY_CODE = "\nimport json,os,time,pwd\nfrom pathlib import Path\nrows=[]\nfor p in Path('/proc').iterdir():\n if not p.name.isdigit():continue\n try:\n  status={k:v.strip() for k,v in (x.split(':',1) for x in (p/'status').read_text().splitlines() if ':' in x)}\n  cmd=(p/'cmdline').read_bytes().replace(b'\\0',b' ').decode(errors='replace')\n  if int(status['Uid'].split()[0])==pwd.getpwnam('etip').pw_uid or any(x in status['Name'] for x in ('redsocks','tcpdump')):\n   rows.append({'pid':int(p.name),'name':status['Name'],'state':status['State'],'fd':len(list((p/'fd').iterdir())),'rss_kib':int(status.get('VmRSS','0 kB').split()[0]),'cmd':cmd})\n except (OSError,KeyError,ValueError):pass\nmem={k:int(v.split()[0]) for k,v in (x.split(':',1) for x in Path('/proc/meminfo').read_text().splitlines())}\nconn=Path('/proc/sys/net/netfilter/nf_conntrack_count')\nsockets={}\nfor p in rows:\n if 'redsocks' in p['name']:\n  try:sockets[str(p['pid'])]=sum(os.readlink(x).startswith('socket:') for x in (Path('/proc')/str(p['pid'])/'fd').iterdir())\n  except OSError:sockets[str(p['pid'])]=None\nprint(json.dumps({'timestamp_ns':time.time_ns(),'processes':rows,'fd_total':sum(p['fd'] for p in rows),'rss_kib':sum(p['rss_kib'] for p in rows),'zombies':sum(p['state'].startswith('Z') for p in rows),'browser_executor_processes':sum(any(x in p['name'].lower() for x in ('chromium','chrome','playwright')) for p in rows),'conntrack':int(conn.read_text()) if conn.exists() else None,'redsocks_socket_fds':sockets,'mem_available_kib':mem['MemAvailable'],'system_memory_used_kib':mem['MemTotal']-mem['MemAvailable']}))\n"
